import 'package:flutter/material.dart';
import '../services/api_client.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key,required this.api,required this.username});final ApiClient api;final String username;@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{int tab=0;String error='';bool busy=false;List<dynamic> posts=[],reports=[];final post=TextEditingController(),accomp=TextEditingController(),blockers=TextEditingController(),plan=TextEditingController(),hours=TextEditingController(text:'8');String type='Update';@override void initState(){super.initState();refresh();}@override void dispose(){post.dispose();accomp.dispose();blockers.dispose();plan.dispose();hours.dispose();super.dispose();}Future<void> refresh()async{setState(()=>{busy=true,error=''});try{final data=await Future.wait([widget.api.call('get_feed'),widget.api.call('get_my_eod_reports')]);if(mounted)setState(()=>{posts=data[0] as List<dynamic>,reports=data[1] as List<dynamic>});}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}Future<void> publish()async{try{await widget.api.call('create_feed_post',{'content':post.text,'post_type':type});post.clear();await refresh();}catch(e){setState(()=>error=e.toString());}}Future<void> submitReport()async{try{await widget.api.call('submit_eod_report',{'accomplishments':accomp.text,'blockers':blockers.text,'next_day_plan':plan.text,'hours_worked':hours.text});accomp.clear();blockers.clear();plan.clear();await refresh();if(mounted)setState(()=>tab=1);}catch(e){setState(()=>error=e.toString());}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(['Team feed','Daily EOD reports','My dashboard'][tab]),actions:[IconButton(onPressed:refresh,icon:const Icon(Icons.refresh))]),body:RefreshIndicator(onRefresh:refresh,child:ListView(padding:const EdgeInsets.all(14),children:[if(error.isNotEmpty)Text(error,style:const TextStyle(color:Colors.red)),if(tab==0)...[card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Share with your team',style:TextStyle(fontWeight:FontWeight.bold)),TextField(controller:post,maxLines:3,maxLength:5000,decoration:const InputDecoration(hintText:'Share an update…')),DropdownButton<String>(value:type,items:['Update','Question','Recognition','Announcement'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v??'Update')),FilledButton.icon(onPressed:publish,icon:const Icon(Icons.send),label:const Text('Publish'))])),for(final p in posts)card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((p['author_name']??'Team member').toString()+' · '+(p['post_type']??'Update').toString(),style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:10),Text((p['content']??'').toString().replaceAll(RegExp(r'<[^>]*>'),'').trim()),Text((p['creation']??'').toString(),style:const TextStyle(fontSize:11))]))],if(tab==1)...[card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('End-of-day report',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),field('Accomplishments *',accomp),field('Blockers',blockers),field('Plan for tomorrow',plan),field('Hours worked',hours),FilledButton.icon(onPressed:submitReport,icon:const Icon(Icons.check),label:const Text('Submit report'))])),for(final r in reports)card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((r['report_date']??'').toString()+' · '+(r['status']??'').toString(),style:const TextStyle(fontWeight:FontWeight.bold)),Text((r['accomplishments']??'').toString().replaceAll(RegExp(r'<[^>]*>'),'').trim()),Text('Hours: '+(r['hours_worked']??0).toString())]))],if(tab==2)card(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Your activity',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),metric('Reports in history',reports.length.toString()),metric('Approved reports',reports.where((r)=>r['status']=='Approved').length.toString()),metric('Hours reported',reports.fold<double>(0,(n,r)=>n+(double.tryParse((r['hours_worked']??0).toString())??0)).toStringAsFixed(1)),metric('Feed posts loaded',posts.length.toString()),const Text('Counts reflect records returned by ERPNext.',style:TextStyle(fontSize:11))])),if(busy)const Center(child:CircularProgressIndicator())])),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.groups),label:'Feed'),NavigationDestination(icon:Icon(Icons.today),label:'EOD'),NavigationDestination(icon:Icon(Icons.insights),label:'Dashboard')]));}Widget card(Widget child)=>Card(color:Colors.white,child:Padding(padding:const EdgeInsets.all(15),child:child));Widget field(String label,TextEditingController c)=>Padding(padding:const EdgeInsets.only(top:10,bottom:5),child:TextField(controller:c,maxLines:label=='Hours worked'?1:3,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));Widget metric(String label,String value)=>Padding(padding:const EdgeInsets.symmetric(vertical:7),child:Row(children:[Expanded(child:Text(label)),Text(value,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:18))]));}
